package com.ashokmart.servlet;
import com.ashokmart.model.*; import com.ashokmart.service.AdminProductService; import com.ashokmart.service.CategoryService; import com.ashokmart.service.impl.CategoryServiceImpl; import com.ashokmart.dao.impl.CategoryDaoImpl; import com.ashokmart.util.DatabaseConnectionPool; import org.slf4j.*; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.IOException;
@WebServlet("/admin/products") public final class AdminProductsServlet extends HttpServlet { private static final Logger LOG=LoggerFactory.getLogger(AdminProductsServlet.class);
 public void doGet(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{AuthenticationResult admin=AdminWebSupport.authenticatedAdmin(req,res);if(admin==null)return;try{DatabaseConnectionPool p=AdminWebSupport.pool(getServletContext());String search=blank(req.getParameter("search"));Long category=parseLong(req.getParameter("category"));Boolean active=parseBool(req.getParameter("active"));Boolean stock=parseStock(req.getParameter("stock"));int page=parseInt(req.getParameter("page"),1);AdminProductService svc=AdminWebSupport.adminProductService(p);req.setAttribute("productPage",svc.getProducts(admin.userId(),new AdminProductQuery(search,category,active,stock,page,12)));req.setAttribute("categories",new CategoryServiceImpl(new CategoryDaoImpl(p)).listCategories());req.setAttribute("searchTerm",search);req.setAttribute("selectedCategory",category);req.setAttribute("selectedActive",req.getParameter("active"));req.setAttribute("selectedStock",req.getParameter("stock"));AdminWebSupport.moveFlash(req.getSession(false),req,"adminSuccess","adminError");req.getRequestDispatcher("/WEB-INF/views/admin-products.jsp").forward(req,res);}catch(IllegalStateException e){LOG.error("Admin product listing failed",e);res.sendError(500,"Products are temporarily unavailable.");}}
 private String blank(String v){return v==null||v.isBlank()?null:v.trim();} private Long parseLong(String v){try{long x=Long.parseLong(v);return x>0?x:null;}catch(Exception e){return null;}} private int parseInt(String v,int d){try{int x=Integer.parseInt(v);return x>0?x:d;}catch(Exception e){return d;}} private Boolean parseBool(String v){return "active".equals(v)?true:"inactive".equals(v)?false:null;} private Boolean parseStock(String v){return "in_stock".equals(v)?true:"out_of_stock".equals(v)?false:null;}
}
